// Icons are redrawn in Omarchy's icon style: the Material Design set that
// Nerd Fonts carries and Omarchy's bar and menus use.
//
// stremio-web renders each icon as an inline <svg> whose only identity is
// its paths, so an icon is recognized by the start of its first path
// (OMATRIMIO_ICONS, generated by scripts/build-icons.py). Its paths are
// hidden by the stylesheet and the replacement is drawn as one more path, in
// currentColor, so every color rule stremio-web has for its icons still
// applies. It is a path rather than a font glyph so it sits exactly centered:
// a glyph is placed by its font's line metrics, a few pixels off.
//
// The original paths stay in the DOM because React owns them; when React
// swaps an icon (outline to filled on the selected tab), it rewrites the
// path, and the replacement follows.
(() => {
    const SVG_NS = 'http://www.w3.org/2000/svg';
    const MARK = 'data-omatrimio-icon';
    const OURS = 'data-omatrimio-glyph';
    const GRID = 24; // Material Design icons are drawn on a 24-unit grid.

    const drawingFor = (svg) => {
        const path = svg.querySelector(`:scope > path:not([${OURS}])`);
        const d = path && path.getAttribute('d');
        return d ? OMATRIMIO_ICONS[d.slice(0, OMATRIMIO_ICON_FINGERPRINT)] : undefined;
    };

    const render = (svg) => {
        const drawing = drawingFor(svg);
        let glyph = svg.querySelector(`:scope > path[${OURS}]`);

        // An icon with no replacement (a brand logo) keeps Stremio's drawing.
        if (drawing === undefined) {
            glyph?.remove();
            svg.removeAttribute(MARK);
            return;
        }

        if (!glyph) {
            glyph = document.createElementNS(SVG_NS, 'path');
            glyph.setAttribute(OURS, '');
            svg.appendChild(glyph);
        }

        // Scale the 24-unit drawing to fill the icon's own box, centered.
        const box = svg.viewBox.baseVal;
        const { x, y, width, height } = box && box.width ? box : { x: 0, y: 0, width: GRID, height: GRID };
        const scale = Math.min(width, height) / GRID;
        const transform = `translate(${x + (width - GRID * scale) / 2} ${y + (height - GRID * scale) / 2}) scale(${scale})`;

        if (glyph.getAttribute('d') !== drawing) glyph.setAttribute('d', drawing);
        if (glyph.getAttribute('transform') !== transform) glyph.setAttribute('transform', transform);
        svg.setAttribute(MARK, '');
    };

    const scan = (node) => {
        if (node.nodeType !== Node.ELEMENT_NODE || node.hasAttribute(OURS)) return;
        if (node.localName === 'svg') render(node);
        node.querySelectorAll('svg').forEach(render);
    };

    const observer = new MutationObserver((records) => {
        for (const record of records) {
            if (record.type === 'attributes') {
                if (record.target.hasAttribute(OURS)) continue;
                const svg = record.target.closest('svg');
                if (svg) render(svg);
            } else {
                record.addedNodes.forEach(scan);
            }
        }
    });

    document.addEventListener('DOMContentLoaded', () => {
        scan(document.body);
        observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['d'],
        });
    });
})();
